def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c == '"':
            i += 1
            while i < n and s[i] != '"':
                if s[i] == '\\':
                    i += 1
                i += 1
            if i >= n:
                return False
        elif c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack.pop() != pairs[c]:
                return False
        i += 1
    return not stack
